-- hook-vault initial schema.
--
-- Requires PostgreSQL 18+ for the native uuidv7() function: the event id is the
-- read cursor, and it must be generated by the single clock that owns the data
-- (the database), never by an application instance.

create table endpoint (
    id              uuid primary key default uuidv7(),
    -- Unguessable path segment. The provider signature is the real
    -- authentication; the slug only removes background scanning noise.
    slug            text not null unique check (slug ~ '^[a-z0-9]{12,64}$'),
    name            text not null check (length(name) between 1 and 200),

    -- Storage policy. NULL means "no limit".
    retention_days  integer check (retention_days is null or retention_days > 0),
    max_bytes       bigint check (max_bytes is null or max_bytes > 0),

    -- Exact counters, maintained by the write path and the reaper so that the
    -- read and panel paths never scan the event table.
    bytes_used      bigint not null default 0 check (bytes_used >= 0),
    events_used     bigint not null default 0 check (events_used >= 0),
    evicted_events  bigint not null default 0,

    -- Inbound verification. The provider secret authenticates the sender; it
    -- cannot reveal any stored payload (those are sealed).
    verify          text not null default 'none'
                    check (verify in ('none', 'github', 'meta', 'stripe', 'generic-hmac')),
    verify_secret   text,
    verify_token    text,

    created_at      timestamptz not null default now(),
    disabled_at     timestamptz,

    constraint verify_needs_secret check (verify = 'none' or verify_secret is not null)
);

create table endpoint_key (
    endpoint_id  uuid not null references endpoint(id) on delete cascade,
    kid          text not null,
    public_key   bytea not null check (octet_length(public_key) = 32),
    -- sha256 of the bearer token derived client-side from the secret key.
    token_sha256 bytea not null check (octet_length(token_sha256) = 32),
    created_at   timestamptz not null default now(),
    revoked_at   timestamptz,
    primary key (endpoint_id, kid)
);

-- One live token per key; the partial index doubles as the auth lookup path.
create unique index endpoint_key_token_idx
    on endpoint_key (token_sha256) where revoked_at is null;

create table event (
    -- The cursor. Time-ordered, generated by Postgres.
    id           uuid primary key default uuidv7(),
    endpoint_id  uuid not null references endpoint(id) on delete cascade,
    received_at  timestamptz not null default now(),
    -- Which key sealed this event: lets a rotated key still open its history.
    kid          text,
    alg          text not null default 'x25519-xsalsa20poly1305-sealed',
    ciphertext   bytea not null,
    size_bytes   integer not null check (size_bytes > 0),
    status       text not null default 'stored' check (status in ('stored', 'rejected')),
    -- Whitelisted, non-secret routing hints; never the body or headers.
    meta         jsonb not null default '{}'::jsonb
);

create index event_cursor_idx on event (endpoint_id, id);
create index event_time_idx on event (endpoint_id, received_at);
